text:
Interactive County Election Map

How to read this map: Counties where Democrat Roy Cooper leads are shaded blue; counties where Republican Michael Whatley leads are shaded red. Darker shades indicate wider percentage-point vote margins. Hover over any county to view exact vote totals, candidate percentages, total ballots cast, and party margin.


View R code
# Diverging red-to-blue binned palette based on DEM minus REP margin (%)
margin_bins &lt;- c(-Inf, -30, -15, -5, 0, 5, 15, 30, Inf)
margin_colors &lt;- c(
  "#991b1b", # REP +30%+
  "#dc2626", # REP +15% to +30%
  "#f87171", # REP +5% to +15%
  "#fecaca", # REP &lt;5%
  "#bfdbfe", # DEM &lt;5%
  "#60a5fa", # DEM +5% to +15%
  "#2563eb", # DEM +15% to +30%
  "#1e3a8a"  # DEM +30%+
)

margin_pal &lt;- colorBin(
  palette = margin_colors,
  domain = nc_counties_sf$margin_pct,
  bins = margin_bins,
  right = FALSE
)

# Build formatted HTML hover tooltips for each of the 100 counties
tooltip_html &lt;- pmap_chr(
  list(
    nc_counties_sf$NAMELSAD,
    nc_counties_sf$leader_party,
    nc_counties_sf$margin_label,
    nc_counties_sf$margin_votes,
    nc_counties_sf$dem_votes,
    nc_counties_sf$dem_pct,
    nc_counties_sf$rep_votes,
    nc_counties_sf$rep_pct,
    nc_counties_sf$other_votes,
    nc_counties_sf$other_pct,
    nc_counties_sf$total_votes
  ),
  \(county_name, leader, m_label, m_votes, d_votes, d_pct, r_votes, r_pct, o_votes, o_pct, tot_votes) {
    badge_bg &lt;- if (leader == "DEM") "#1d4ed8" else "#dc2626"
    lead_sign &lt;- sprintf("+%s votes", comma(abs(m_votes)))

    sprintf(
      "&lt;div style='min-width:240px;'&gt;
        &lt;div style='display:flex;justify-content:space-between;align-items:center;gap:8px;border-bottom:1px solid rgba(255,255,255,0.18);padding-bottom:6px;margin-bottom:7px;'&gt;
          &lt;strong style='font-size:14px;color:#ffffff;'&gt;%s&lt;/strong&gt;
          &lt;span style='background:%s;color:#fff;font-size:11px;font-weight:700;padding:2px 7px;border-radius:4px;'&gt;%s&lt;/span&gt;
        &lt;/div&gt;
        &lt;table style='width:100%%;font-size:12.5px;border-collapse:collapse;color:#e2e8f0;'&gt;
          &lt;tr&gt;
            &lt;td style='padding:2px 0;'&gt;&lt;span style='color:#60a5fa;font-weight:700;'&gt;●&lt;/span&gt; Cooper (DEM)&lt;/td&gt;
            &lt;td style='text-align:right;padding:2px 6px;'&gt;%s&lt;/td&gt;
            &lt;td style='text-align:right;font-weight:700;color:#ffffff;'&gt;%.1f%%&lt;/td&gt;
          &lt;/tr&gt;
          &lt;tr&gt;
            &lt;td style='padding:2px 0;'&gt;&lt;span style='color:#f87171;font-weight:700;'&gt;●&lt;/span&gt; Whatley (REP)&lt;/td&gt;
            &lt;td style='text-align:right;padding:2px 6px;'&gt;%s&lt;/td&gt;
            &lt;td style='text-align:right;font-weight:700;color:#ffffff;'&gt;%.1f%%&lt;/td&gt;
          &lt;/tr&gt;
          &lt;tr&gt;
            &lt;td style='padding:2px 0;color:#94a3b8;'&gt;● Other (LIB/GRE)&lt;/td&gt;
            &lt;td style='text-align:right;padding:2px 6px;color:#94a3b8;'&gt;%s&lt;/td&gt;
            &lt;td style='text-align:right;color:#94a3b8;'&gt;%.1f%%&lt;/td&gt;
          &lt;/tr&gt;
        &lt;/table&gt;
        &lt;div style='display:flex;justify-content:space-between;border-top:1px solid rgba(255,255,255,0.15);margin-top:6px;padding-top:5px;font-size:11.5px;color:#cbd5e1;'&gt;
          &lt;span&gt;Total: &lt;strong&gt;%s&lt;/strong&gt;&lt;/span&gt;
          &lt;span&gt;Margin: &lt;strong&gt;%s&lt;/strong&gt;&lt;/span&gt;
        &lt;/div&gt;
      &lt;/div&gt;",
      county_name, badge_bg, m_label,
      comma(d_votes), d_pct,
      comma(r_votes), r_pct,
      comma(o_votes), o_pct,
      comma(tot_votes), lead_sign
    )
  }
) |&gt;
  map(HTML)

# Render interactive Leaflet choropleth
leaflet(nc_counties_sf, options = leafletOptions(minZoom = 6, maxZoom = 11)) |&gt;
  addProviderTiles(providers$CartoDB.Positron) |&gt;
  setView(lng = -79.45, lat = 35.55, zoom = 7) |&gt;
  addPolygons(
    fillColor = ~margin_pal(margin_pct),
    fillOpacity = 0.84,
    color = "#ffffff",
    weight = 1.1,
    opacity = 1,
    highlightOptions = highlightOptions(
      weight = 2.6,
      color = "#0f172a",
      fillOpacity = 0.95,
      bringToFront = TRUE
    ),
    label = tooltip_html,
    labelOptions = labelOptions(
      className = "nc-county-tooltip",
      direction = "auto",
      sticky = TRUE,
      opacity = 1
    )
  ) |&gt;
  addLegend(
    position = "bottomleft",
    colors = rev(margin_colors),
    labels = c(
      "DEM +30%+",
      "DEM +15% to +30%",
      "DEM +5% to +15%",
      "DEM &lt;5%",
      "REP &lt;5%",
      "REP +5% to +15%",
      "REP +15% to +30%",
      "REP +30%+"
    ),
    opacity = 0.88,
    title = "Vote Margin (U.S. Senate)"
  )







Election & Contest: Nov. 3, 2026 General Election — U.S. Senate (North Carolina) Data Source: NC State Board of Elections (Unofficial Results) & U.S. Census Bureau TIGER/Cartographic Boundaries
